parameters.jsCode:
const raw = $input.first().json.output;
let text = (typeof raw === 'string' ? raw : '').trim();

// Slack mrkdwn uses single asterisks. The model emits ** despite the prompt
// forbidding it, and Slack shows those as literal characters. Fixed here rather
// than asked for again.
text = text.replace(/\*{2,}/g, '*');

// --- the confirmation marker, normalised ---------------------------------
// Gate Context matches the marker at the end of the message, so anything she
// adds to it breaks the gate. On 2026-08-30 she wrote "Confirm to cancel both.
// (y/n)" and the cancellation was refused as NOT_CONFIRMED - safe, but two
// wasted turns, and she rephrases constantly. The gate stays strict; the line
// is put back into its canonical form here instead.
text = text.replace(
  /(?:Reply only with "yes"[^\n]*\n)?Confirm to (book|cancel|move)\b[^.\n!?]{0,40}([.!]?)(\s*\((?:y\/n|yes\/no)\))?\s*$/i,
  (whole, verb) => {
    const v = verb.toLowerCase();
    const neg = v === 'cancel' ? 'keep it' : (v === 'move' ? 'keep it where it is' : 'change anything');
    return 'Reply only with "yes" to ' + v + ', or "no" to ' + neg + '.\nConfirm to ' + v + '.';
  });

// --- vocabulary the requester should never see ---------------------------
// "Priority" and "Last Resort" are Airtable column names. Tara, 2026-08-30:
// "just dont mention priority and last resort" - "last resort" makes a
// preference sound like a rule. v92 said so in the prompt and the words still
// appeared in five replies, so it is done here instead, where compliance is
// not required.
// Each pattern swallows the article in front of it, or the replacement lands
// inside the old one - "The the rooms normally used", "is a a room normally
// used". Longest phrases first.
const SAY = [
  [/\b(these|those)\s+priority rooms\b/gi,      '$1 rooms'],
  [/\b(the)\s+priority rooms\b/gi,             '$1 rooms normally used'],
  [/\b(a|an)\s+priority room\b/gi,              'a room normally used'],
  [/\bpriority rooms\b/gi,                      'rooms normally used'],
  [/\bpriority room\b/gi,                       'room normally used'],
  [/\b(a|an)\s+last[- ]resort room\b/gi,        'not one of the usual rooms'],
  [/\b(these|those|the)\s+last[- ]resort rooms\b/gi, '$1 other rooms'],
  [/\blast[- ]resort rooms\b/gi,                'other rooms'],
  [/\blast[- ]resort room\b/gi,                 'another room'],
  [/\b(a|an)\s+last[- ]resort choice\b/gi,      'not the usual choice'],
  [/\blast[- ]resort choice\b/gi,               'not the usual choice'],
  [/\bas a last resort\b/gi,                    'if nothing else is free'],
  [/\bprioriti[sz]ed\b/gi,                      'normally used']
];
for (const [re, to] of SAY) text = text.replace(re, to);

// --- the weekday she prints beside a date --------------------------------
// Gate Context resolves the date and states the weekday, and she has still
// written "September 9, 2027 (Wed)" for a Thursday three times - twice in a
// booking summary, which is the line a requester scans before saying yes. The
// date is the fact; the weekday is derived from it, so it is corrected here
// rather than trusted.
const DAYS  = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const SHORT = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const MONTHS = { january:0, february:1, march:2, april:3, may:4, june:5, july:6,
                 august:7, september:8, october:9, november:10, december:11 };
const dayOf = (y, m, d) => new Date(Date.UTC(y, m, d)).getUTCDay();

// "September 9, 2027 (Wed)" / "9 September 2027 (Wed)"
// The whole parenthesised word is captured, not just its three-letter prefix.
// The old form captured only the abbreviation and swapped that, so a wrong long
// day name became a mangled one: "(Wednesday)" for a Thursday had "Wed" replaced
// with "Thu" and kept the tail, printing "(Thunesday)" in a booking summary on
// 2026-09-03. That then read like the model corrupting a string, when it was this
// correction doing it. Long form in, long form out; short in, short out - and a
// value already mangled by the old code is repaired, since it still starts with a
// real abbreviation.
text = text.replace(
  /\b([A-Za-z]+)\s+(\d{1,2}),?\s+(\d{4})\s*\(((?:Sun|Mon|Tue|Wed|Thu|Fri|Sat)[a-z]*)\)/g,
  (whole, mon, d, y, written) => {
    const m = MONTHS[String(mon).toLowerCase()];
    if (m === undefined) return whole;
    const idx = dayOf(+y, m, +d);
    const right = written.length > 3 ? DAYS[idx] : SHORT[idx];
    return written === right ? whole : whole.replace('(' + written + ')', '(' + right + ')');
  });

// "Wednesday, September 9, 2027"
text = text.replace(
  /\b(Sunday|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday),\s+([A-Za-z]+)\s+(\d{1,2}),?\s+(\d{4})/g,
  (whole, named, mon, d, y) => {
    const m = MONTHS[String(mon).toLowerCase()];
    if (m === undefined) return whole;
    const right = DAYS[dayOf(+y, m, +d)];
    return right === named ? whole : right + whole.slice(named.length);
  });

// --- internal vocabulary that leaked during QA ---------------------------
// "deviation" is how the room ranking is described internally. A requester
// reading "Room: Studio 5 (deviation: another room for post mixing)" is being
// shown a schema, not an explanation - the same complaint Tara made about
// "priority" and "last resort" on 2026-08-30. "BLOCKED - " is the prefix the
// guards use to make a refusal unmissable to the model; it is not for a person.
text = text.replace(/^\s*BLOCKED\s*[-\u2013\u2014:]\s*/i, '');
// Each pattern swallows the article in front of it. v100 replaced the noun
// alone and shipped "Studio 3 is a exception for VO Recording" - the same
// mistake the priority/last-resort list above already carries a warning about.
const DEV = [
  [/\bis\s+an?\s+deviation\s+from\s+the\s+usual\s+rooms?\b/gi, 'is not one of the usual rooms'],
  [/\ban?\s+deviation\s+from\b/gi, 'different from'],
  [/\bis\s+an?\s+deviations?\b/gi, 'is not a usual room'],
  [/\ban?\s+deviations?\b/gi,       'an exception'],
  [/\(\s*deviations?:\s*/gi,        '('],
  [/\bdeviations?:\s*/gi,            'note: '],
  [/\bdeviations?\b/gi,              'exception']
];
for (const [re, to] of DEV) text = text.replace(re, to);

// --- the label on the booker line ----------------------------------------
// Every summary says "Booked by:" except when it says "Booking Owner:".
text = text.replace(/\*\s*Booking Owner\s*:\s*\*/gi, '*Booked by:*');
// She also drops the space - "*Bookedby:* Tara Lim" on 2026-08-30. Both
// forms are normalised here, before the name repair below, or that repair
// does not match the line it is meant to fix.
text = text.replace(/\*\s*Bookedby\s*:\s*\*/gi, '*Booked by:*');

// --- the prompt's own numbering ------------------------------------------
// "since rule 1 says we never move or cancel an existing booking to clear a
// room" went out on 2026-09-01. The rules are numbered for the model's benefit;
// a requester has no rule 1 and hearing about one makes a studio policy sound
// like a software constraint. The substance is kept, the citation dropped.
// Removing the citation can leave the sentence starting lowercase. v115 shipped
// "Rule 1 says we never delete..." -> "we never delete...", mid-paragraph and
// uncapitalised. So the sentence-initial form carries the following letter into
// the match and puts it back in upper case; the mid-sentence form does not need
// to, because the connector before it survives.
text = text.replace(
  /(^|[\n.!?]\s*)rule\s+\d+\s+(?:says|states|requires)\s+(?:that\s+)?([a-z])/gi,
  (whole, pre, ch) => pre + ch.toUpperCase());
const CITE = [
  [/\b(since|because|as)\s+rule\s+\d+\s+(?:says|states|requires)\s+(?:that\s+)?/gi, '$1 '],
  [/\b(?:per|under|by)\s+rule\s+\d+\s*,?\s*/gi, ''],
  [/\brule\s+\d+\s+(?:says|states|requires)\s+(?:that\s+)?/gi, ''],
  [/\b(?:the\s+)?(?:three\s+)?unoverridable\s+rules?\b/gi, 'the booking rules'],
  // Singular, because what follows is a singular verb: "rule 1 is absolute"
  // became "the booking rules is absolute". Third grammar break from this
  // family of rewrites - the article one, the capitalisation one, then
  // agreement. A regex cannot promise the result reads correctly, so the sweep
  // below catches the disagreement these rewrites can leave behind.
  [/\brule\s+\d+\b/gi, 'a standing rule']
];
for (const [re, to] of CITE) text = text.replace(re, to);
text = text.replace(/\brules\s+is\b/gi, 'rules are')
           .replace(/\ba\s+standing\s+rule\s+are\b/gi, 'a standing rule is');

// --- what the tools actually returned this turn --------------------------
// intermediateSteps arrive on this node's input, so reading them costs nothing
// and hangs nothing (gotcha 11). Extracted up here because two blocks below
// need the evidence, not just the claim check that came first.
let steps = null;
try {
  const st = $input.first().json.intermediateSteps;
  if (Array.isArray(st)) steps = st;
} catch (e) {}

// Everything a tool returned or was handed this turn, as one lowercase string.
// A name or title found in here was reported by a tool and is not the model's
// invention, whatever else is wrong with the sentence around it.
let evidence = '';
try {
  for (const st of (steps || [])) {
    evidence += ' ' + JSON.stringify(((st || {}).action || {}).toolInput || '');
    evidence += ' ' + String((st || {}).observation || '');
  }
  evidence = evidence.replace(/\s+/g, ' ').toLowerCase();
} catch (e) { evidence = ''; }

// Edit distance, capped - only ever asked about short names.
const editDist = (a, b) => {
  a = String(a); b = String(b);
  if (a === b) return 0;
  if (!a.length || !b.length) return Math.max(a.length, b.length);
  let prev = [];
  for (let j = 0; j <= b.length; j++) prev[j] = j;
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1,
                        prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length];
};

// --- who actually booked it ----------------------------------------------
// The model retypes the booker's name and has corrupted it: "Tara Lim" came
// back "Tara Inf" on 2026-08-30, in the line a requester scans before saying
// yes. The name is known from Airtable, so it is written rather than trusted.
// The calendar entry was never at risk - its "Booked by" comes from Get Booker
// through a workflow input, and the model never supplies it.
//
// It is NOT always the requester. A cancel or a lookup shows someone else's
// booking, and until v119 this block relabelled it: asked to cancel a booking
// held by another engineer on 2026-09-03, Find Booking returned the real owner
// and this line replaced their name with the requester's - turning the refusal
// that follows ("that is not yours") into a contradiction of the summary right
// above it, in the one context where the name is the whole point.
//
// So it only overwrites a name that is BOTH absent from what the tools returned
// this turn and a near-miss of the real one. A corruption is neither reported
// nor plausible; a third party's name is reported, and is nobody's typo.
try {
  const realBooker = String($('Get Booker').first().json.fields.Name || '').trim();
  if (realBooker) {
    const target = realBooker.toLowerCase();
    text = text.replace(/(\*Booked by:\*[ \t]*)([^\n*]+)/g, (whole, lead, got) => {
      const name = got.trim();
      if (!name || name === realBooker) return whole;
      // reported by a tool this turn - not the model's to be corrected
      if (evidence && evidence.indexOf(name.toLowerCase()) !== -1) return whole;
      // a corruption stays close to the original; a different person does not
      const d = editDist(name.toLowerCase(), target);
      if (d > Math.max(2, Math.floor(target.length * 0.4))) return whole;
      return lead + realBooker;
    });
  }
} catch (e) {}

// --- a date written without a year --------------------------------------
// Both corrections above need a four-digit year. She also writes "next
// Wednesday, September 9" with no year, and that form went out uncorrected for
// a Thursday on 2026-08-30. The year comes from the date Gate Context already
// resolved rather than from a second copy of the QA year shift; with no year to
// work from the line is left alone.
//
// The day number needs (?!\d) as well as the year lookahead. Without it
// `\d{1,2}` backtracks: on "Friday, September 10, 2027" the lookahead rejects
// d=10, the engine retries with d=1, the lookahead passes, and the line is
// rewritten to the weekday of September *1st*. Every dated weekday with a
// two-digit day came out wrong from v104 to v118, and it silently undid the
// dated correction 60 lines above - which is how it hid: on 2026-09-03
// "next Wednesday, September 10, 2027" was corrected to Friday and then put
// back to Wednesday, so the block above looked like it was doing nothing.
// Only prose lines carry this form; summaries write "September 10, 2027 (Fri)"
// and go through the abbreviation block instead, which is why nobody saw it.
//
// This is the only node lookup added in v104. v102 added three at once and
// Guard Probe began timing out at 60s on every message, so they go back one at
// a time and each one is checked against a real execution before the next.
let refYear = null;
try {
  const gc = $('Gate Context').first().json;
  const ym = (String(gc.dateNotice || '') + ' ' + String(gc.pastDateNotice || '')).match(/\b(20\d{2})\b/);
  if (ym) refYear = +ym[1];
} catch (e) {}
if (refYear) {
  text = text.replace(
    /\b(Sunday|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday),\s+([A-Za-z]+)\s+(\d{1,2})(?!\d)(?!\s*,?\s*\d{4})/g,
    (whole, named, mon, d) => {
      const m = MONTHS[String(mon).toLowerCase()];
      if (m === undefined) return whole;
      const right = DAYS[dayOf(refYear, m, +d)];
      return right === named ? whole : right + whole.slice(named.length);
    });
}

// --- a duration nobody asked for ----------------------------------------
// Gate Context spots a start time with no end and tells her to say what length
// she is assuming. She did it once on 2026-08-30 and ignored it the next time,
// which is what an instruction in the prompt is worth. Written here when the
// summary does not already say it.
//
// Uses the same $('Gate Context') lookup as the weekday correction above - v105
// adds no new one. Guard Probe ran 70ms with that lookup in v104.
try {
  const startOnly = String($('Gate Context').first().json.startOnlyNotice || '').length > 0;
  if (startOnly && /Confirm to book\./i.test(text) && !/\bassum/i.test(text)) {
    const t = text.match(/\*Time:\*\s*(\d{1,2})(?::(\d{2}))?\s*(AM|PM)\s*[-\u2013\u2014]\s*(\d{1,2})(?::(\d{2}))?\s*(AM|PM)/i);
    if (t) {
      const to24 = (h, ap) => (String(ap).toUpperCase() === 'PM' ? (+h % 12) + 12 : (+h % 12));
      const mins = (to24(t[4], t[6]) * 60 + (+t[5] || 0)) - (to24(t[1], t[3]) * 60 + (+t[2] || 0));
      if (mins > 0) {
        const hrs = Math.floor(mins / 60), rem = mins % 60;
        const len = (hrs ? hrs + ' hour' + (hrs === 1 ? '' : 's') : '')
                  + (hrs && rem ? ' ' : '') + (rem ? rem + ' minutes' : '');
        text = 'Assuming ' + len + ' \u2014 tell me if that is wrong.\n\n' + text;
      }
    }
  }
} catch (e) {}

// --- a note that contradicts the ranking ---------------------------------
// "Studio 7 is outside the usual rooms for Post Mixing (Studio 7 and 8 are the
// usual rooms for Post Mixing, so Studio 7 is one of the usual rooms)" went out
// on 2026-08-30. Studio 7 is first in that ranking; the note had carried over
// from an earlier turn about Studio 3. The ranking is known here, so a note the
// ranking contradicts is removed rather than sent.
//
// $('Room Table') is the last of the three lookups v102 added and the only one
// still unaccounted for - Gate Context was cleared at 70ms in v104. It ships on
// its own so the next execution's timing says plainly whether this is what hung
// Guard Probe for 60s.
try {
  const table = String($('Room Table').first().json.roomTable || '');
  const esc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  text = text.replace(/^[ \t]*\*Note:\*[^\n]*\n?/gim, line => {
    const m = line.match(/\*Note:\*\s*(.+?)\s+is\s+(?:outside|not one of|not a)\b[^\n]*?\bfor\s+([A-Za-z0-9 ]+?)\s*[.,(]/i);
    if (!m) return line;
    const room = m[1].trim(), type = m[2].trim();
    const row = table.split('\n').find(r => new RegExp('^-\\s*' + esc(type) + '\\s+\u2014', 'i').test(r.trim()));
    if (!row) return line;
    return new RegExp('\\b' + esc(room) + '\\b', 'i').test(row) ? '' : line;
  });
} catch (e) {}

// --- a claim with nothing behind it --------------------------------------
// On 2026-08-30 she answered an approved booking with "Booked. That is a bit
// shorter than VO Recording sessions usually run" without calling Book Session
// at all, copying an almost identical exchange from two turns earlier. Nothing
// reached the calendar and the requester was told it had. One run in 120, and
// the worst sentence this bot can produce: every other guard stops a wrong
// booking being made, none of them stops one being claimed.
//
// The obvious check is unavailable - $('Book Session') hangs the task runner
// for 60s (CLAUDE.md gotcha 11, PENDING 14). This reads the agent's own
// intermediateSteps, which arrive on this node's input, so there is no node
// lookup to hang. It is also a stronger check than asking whether the node ran:
// it requires the tool to have returned a success status on THIS turn.
//
// Conservative by design. If the steps are missing - the agent option off, or an
// older execution - nothing is rewritten and claimProbe says so. Telling someone
// a real booking failed would be worse than the bug this fixes.
let claimProbe = 'no claim';
const CLAIMS = [
  [/^\s*\*?Booked\b|\bhas been booked\b/i, [['book session', ['CREATED']], ['book series', ['BOOKED_SERIES']]], 'booked'],
  [/^\s*\*?Cancell?ed\b/i,                   [['cancel booking', ['CANCELLED']]],                                 'cancelled'],
  [/^\s*\*?Moved\b/i,                        [['move booking',   ['MOVED', 'PARTIAL']]],                          'moved']
];
for (const [re, wanted, word] of CLAIMS) {
  if (!re.test(text)) continue;
  if (!steps) { claimProbe = word + ': no intermediateSteps on input'; break; }
  const ran = steps.some(st => {
    const tool = String((((st || {}).action) || {}).tool || '').replace(/[_\s]+/g, ' ').toLowerCase();
    const obs = String((st || {}).observation || '');
    return wanted.some(pair => tool === pair[0] && pair[1].some(s => obs.indexOf('"' + s + '"') !== -1));
  });
  claimProbe = word + ': ' + (ran ? 'confirmed' : 'NOT FOUND');
  if (!ran) {
    text = 'Sorry \u2014 that did not go through, and I should not have said otherwise. Nothing was '
         + word + '. Say "yes" again and I will retry it.';
  }
  break;
}

// --- an offer this turn's check contradicts ------------------------------
// She has presented a room as available that was not. Twice on 2026-08-30: once
// where the availability call came back BAD_WINDOW - the timestamp carried an
// invisible character and nothing was checked at all - and once where the room
// was held by a booking made minutes earlier. Book Session refused both at
// confirmation, so nothing was double-booked, but the requester was shown a room
// they could not have and a turn was wasted each time.
//
// This deliberately does NOT require a check to exist. Availability is often
// established a turn earlier - "is Studio 3 free?" then "book it" - and demanding
// a same-turn call would break that ordinary flow. It only refuses to let the
// summary stand when the evidence from THIS turn contradicts it: the check
// errored, or it named that very room busy. Both are cases where the offer is
// known to be wrong rather than merely unproven.
try {
  if (steps && /Confirm to book\.\s*(?:\(yes\/no\)\s*)?$/i.test(text)) {
    const rm = text.match(/\*Room:\*\s*([^\n(*]+)/i);
    const room = rm ? rm[1].trim() : '';
    let wrong = '';
    let followup = '';
    for (const st of steps) {
      const tool = String((((st || {}).action) || {}).tool || '').replace(/[_\s]+/g, ' ').toLowerCase();
      if (tool !== 'room availability') continue;
      let parsed = null;
      try { parsed = JSON.parse(String((st || {}).observation || '')); } catch (e) {}
      const rows = Array.isArray(parsed) ? parsed : (parsed ? [parsed] : []);
      for (const r of rows) {
        if (!r) continue;
        if (r.status === 'BAD_WINDOW' || r.status === 'PAST_DATE' || r.status === 'NO_REFERENCE_DATA') {
          wrong = 'I could not actually check ' + (room || 'that room') + ' for this time (the availability check did not run)';
          followup = 'Let me re-check the room and time before you confirm anything.';
        } else if (room && r.asked && String(r.asked.room || '').toLowerCase() === room.toLowerCase()
                   && ['BUSY', 'UNKNOWN_ROOM', 'NOT_RUN_HERE'].indexOf(String(r.asked.status || '')) !== -1) {
          const s = String(r.asked.status || '');
          if (s === 'BUSY') {
            // Preemption exception: a higher-priority request intentionally summarizes a HELD room
            // (the current holder will be asked to move). The prompt marks such a summary with a
            // "current holder" note, so a busy room there is expected, not a mistake — leave it.
            if (!/current holder|held by the current|ask (?:them|the holder) to move|requesting it from/i.test(text)) {
              wrong = room + ' is already booked for that time';
              followup = 'Want me to look at another time, or a different room?';
            }
          } else if (s === 'UNKNOWN_ROOM') {
            wrong = room + ' is not a room I recognize';
            followup = 'Which room did you mean?';
          } else {
            wrong = room + ' is not one of the usual rooms for this session type';
            followup = 'Want me to use one of the usual rooms, or set it up in ' + room + ' as an exception?';
          }
        }
      }
    }
    if (wrong) {
      text = 'Hold on \u2014 ' + wrong + ', so I should not have offered it. ' + followup;
    }
  }
} catch (e) {}

// --- a booking the lookup did not return --------------------------------
// On 2026-09-03, asked what was booked in Studio 4, Find Booking returned five
// bookings and none of them was PRUNEOK - it had been deleted minutes earlier.
// She answered "PRUNEOK / Bea Jose / TL, 2:00 PM - 4:00 PM" anyway, from
// conversation memory, with the correct answer sitting in front of her. Twice
// before that she named a booking that no longer existed and a roster that was
// missing eleven people. The tools were right every time; the sentence was not.
//
// Only applies to a turn that actually looked a day up, so booking summaries
// and titles the requester just typed are untouched: those turns do not call
// Find Booking, and on the ones that do - a cancel or a move - the title comes
// back in the result and matches.
try {
  if (steps) {
    const LOOKUPS = ['find booking', 'list events'];
    let looked = false;
    let haystack = '';
    for (const st of steps) {
      const tool = String((((st || {}).action) || {}).tool || '').replace(/[_\s]+/g, ' ').toLowerCase();
      // Anything the model passed *into* a tool is fair game to repeat back.
      haystack += ' ' + JSON.stringify(((st || {}).action || {}).toolInput || '');
      haystack += ' ' + String((st || {}).observation || '');
      if (LOOKUPS.indexOf(tool) !== -1) looked = true;
    }
    if (looked) {
      const norm = s => String(s).replace(/\s+/g, ' ').trim().toLowerCase();
      const hay = norm(haystack);
      const claimed = [];
      const grab = re => {
        let m;
        while ((m = re.exec(text)) !== null) {
          const s = String(m[1]).trim();
          if (s.indexOf(' / ') !== -1) claimed.push(s);
        }
      };
      grab(/\*([^*\n]{3,80})\*/g);      // *TITLE / Client / II*
      grab(/"([^"\n]{3,80})"/g);         // "TITLE / Client / II"
      const invented = claimed.filter(t => hay.indexOf(norm(t)) === -1);
      if (invented.length) {
        text = 'Let me check that again - I named ' + (invented.length === 1 ? 'a booking' : 'bookings')
             + ' that did not come back in the calendar for that day, so I should not have '
             + 'told you about ' + (invented.length === 1 ? 'it' : 'them') + '. Ask me once more '
             + 'and I will read the day fresh.';
      }
    }
  }
} catch (e) {}

const fallback = "Sorry — I lost the thread on that one. Could you say it again?";
return [{ json: { output: text.length ? text : fallback, claimProbe: claimProbe } }];

// Collapses Slack history back to ONE item - a multi-item node in the agent's
// main chain breaks paired-item resolution (HANDOFF 7.2). Everything downstream
// reads this node with .first().
//
// The gate: `confirmed` is true only when the last thing Jessie said in this DM
// was a summary ending in the marker line, AND the requester has said something
// since. Send Reply runs after the agent, so a summary written in the current
// turn is not in Slack yet - a same-turn booking cannot pass this. The model
// supplies no part of it.
const MARKERS = { book: 'confirm to book.', cancel: 'confirm to cancel.', move: 'confirm to move.' };
// A reply only approves something. A fresh instruction is not an approval, which
// is how a booking once went through with no summary: the previous bot message
// still ended with the marker, and the next request counted as the yes.
const isNewRequest = t => (/\b(book|rebook|reschedule|cancel|move)\b/i.test(t) && t.trim().length > 30)
                          || /^reset$/i.test(t.trim());   // reset clears memory, it approves nothing
const BOT_USER = 'U0BNQL8KFKR';   // Jessie's own Slack user, seen on her replies
// Anything sent through the Claude Slack connector arrives with a trailing
// "*Sent using* <@U0AVDBNH1K4>". Every whole-message match has to see past it,
// or the message is a different string than the one that was typed.
const clean = s => String(s || '').replace(/\*sent using\*[\s\S]*$/i, '').trim();

const trigger = $('Slack Trigger').first().json || {};
const booker = $('Get Booker').first().json || {};
let msgs = [];
try { msgs = $('Get Recent Messages').all().map(i => (i && i.json) ? i.json : {}); } catch (e) { msgs = []; }

const isBot = m => Boolean(m.bot_id) || m.subtype === 'bot_message' || m.user === BOT_USER;

// Memory epoch. Only a typed "reset" ends the conversation for memory purposes.
// A finished booking used to end it too, so the next request could not inherit
// its client or session type - but that also meant "cancel that" straight after
// a booking had nothing to refer to. Inheriting is now caught by the summary,
// which is read before anything is created; forgetting was not caught by
// anything. Tara's call, 2026-08-30.
//
// Held in workflow static data and only ever moves forward. Deriving it from
// the history window alone was wrong: once the marker aged out of the window
// the epoch fell back to empty, the key changed and the thread lost context.
// Read off this message rather than waiting for it to appear in the history
// window. The epoch used to advance only because the loop below found "reset"
// in the last 12 messages, which depends on Slack having already returned the
// message that triggered this run.
const isReset = /^reset$/i.test(clean(trigger.text));

const store = $getWorkflowStaticData('global');
const slackUser = String($('Slack Trigger').first().json.user || '');
const storeKey = 'epoch_' + slackUser;
let epoch = String(store[storeKey] || '');
for (const m of msgs) {
  const t = clean(m.text);
  const ts = String(m.ts || '');
  const marks = !isBot(m) && /^reset$/i.test(t);
  if (marks && ts && parseFloat(ts) > parseFloat(epoch || '0')) { epoch = ts; break; }
  if (marks) break;
}
if (isReset && trigger.ts && parseFloat(trigger.ts) > parseFloat(epoch || '0')) {
  epoch = String(trigger.ts);
}
store[storeKey] = epoch;

// Slack returns newest first. Walk back to the first bot message, counting any
// requester messages passed on the way - those are the reply that came after it.
let repliedSince = 0, lastBotText = '', found = false, sawNewRequest = false;
for (const m of msgs) {
  if (isBot(m)) { lastBotText = String(m.text || ''); found = true; break; }
  const t = String(m.text || '');
  if (t.trim()) { repliedSince++; if (isNewRequest(t)) sawNewRequest = true; }
}


// --- what day it is, once, for everything below --------------------------
// YEAR_SHIFT matches the prompt's plus({ years: 1 }) QA convention. Both must
// go to 0 together before launch, or the model and this code disagree about
// what day it is - and this node decides what "next Thursday" means.
const YEAR_SHIFT = 1;
const DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const MONTHNAMES = ['January','February','March','April','May','June','July','August',
                    'September','October','November','December'];
const manila = new Date(Date.now() + 8 * 3600 * 1000);
const today = new Date(Date.UTC(manila.getUTCFullYear() + YEAR_SHIFT, manila.getUTCMonth(),
                                manila.getUTCDate()));
const addDays = (d, n) => new Date(d.getTime() + n * 86400000);
const show = d => DAYS[d.getUTCDay()] + ', ' + d.getUTCDate() + ' ' + MONTHNAMES[d.getUTCMonth()]
                + ' ' + d.getUTCFullYear() + ' (' + d.toISOString().slice(0, 10) + ')';

// --- a date that has already passed --------------------------------------
// Read out of the message here rather than left to the model to notice. Only
// dates carrying an explicit year are checked: without one, a date resolves
// against "today" in the prompt and cannot be in the past.
const MONTHS = { jan:0, feb:1, mar:2, apr:3, may:4, jun:5, jul:6, aug:7, sep:8, oct:9, nov:10, dec:11 };
function explicitDate(text) {
  const t = String(text || '');
  let m;
  // 2026-07-01
  m = t.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
  if (m) return { y:+m[1], mo:+m[2]-1, d:+m[3], shown:m[0] };
  // 1 July 2026  /  1 Jul 2026
  m = t.match(/\b(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]{3,9})\.?,?\s+(\d{4})\b/);
  if (m && MONTHS[m[2].slice(0,3).toLowerCase()] !== undefined)
    return { y:+m[3], mo:MONTHS[m[2].slice(0,3).toLowerCase()], d:+m[1], shown:m[0] };
  // July 1 2026  /  July 1st, 2026
  m = t.match(/\b([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b/);
  if (m && MONTHS[m[1].slice(0,3).toLowerCase()] !== undefined)
    return { y:+m[3], mo:MONTHS[m[1].slice(0,3).toLowerCase()], d:+m[2], shown:m[0] };
  return null;
}
let pastDate = '', pastDateNotice = '';
const pastHit = explicitDate(String(trigger.text || ''));
if (pastHit) {
  // Compared against the date the model is told it is, not the real one. With
  // YEAR_SHIFT on those are a year apart, so a 2027 date that had already passed
  // from the requester's point of view was sailing through unflagged.
  const asked = Date.UTC(pastHit.y, pastHit.mo, pastHit.d);
  if (asked < today.getTime()) {
    pastDate = pastHit.shown;
    pastDateNotice = 'THE DATE THEY GAVE HAS ALREADY PASSED: ' + pastHit.shown + '. Before anything else, '
      + 'tell them that date is in the past and ask for the correct one. Do not ask for the session type, '
      + 'the client, the project or the engineer, and do not attempt to book it.';
  }
}

// What counts as a yes. Until now `confirmed` only required that the requester
// had said something that was not a fresh instruction - so "no" passed the gate.
// Harmless while the model still had to decide to act; not harmless once
// cancelNotice started telling it the cancellation was approved. Tara's call,
// 2026-08-30: the requester is offered y/n and the gate matches that literally,
// with nothing interpreted.
const YES = /^(y|yes|yeah|yep|yup|ok|okay|k|sure|sige|oo|opo|confirm|confirmed|correct|right|go|go ahead|do it|proceed|book it|cancel it|yes please|please do|\u{1F44D}|\u{2705})$/iu;
const NO  = /^(n|no|nope|nah|hindi|wait|stop|hold on|not yet|never ?mind|wrong|change it)$/i;
const said = clean(trigger.text).replace(/[.!,]+$/, '').trim();
const saidYes = YES.test(said);
const saidNo  = NO.test(said);

// (y/n) is part of what she now writes; the marker match ignores it, so a reply
// still lands whether or not the model remembered to add it.
// --- relative dates, resolved here rather than by the model ---------------
// "next Thursday" resolved to 2027-09-09 in one run and 2027-09-02 seven
// minutes later, from the same prompt date. She also printed the wrong weekday
// beside a right date - "September 9, 2027 (Wed)" for a Thursday - which is
// worse, because the weekday is what a booker scans before typing y.
//
// Tara's rule, 2026-08-30: "next Thursday" is the Thursday of NEXT week,
// because "this Thursday" is the one in the current week. Weeks start Monday.
const weekMonday = addDays(today, -((today.getUTCDay() + 6) % 7));
const dayIndex = n => DAYS.map(d => d.toLowerCase()).indexOf(String(n).toLowerCase());
const dateLines = [];
let primaryDate = null;
const seenPhrase = {};
const note = (phrase, date, extra) => {
  const k = phrase.toLowerCase();
  if (seenPhrase[k]) return;
  seenPhrase[k] = 1;
  if (!primaryDate) primaryDate = date;
  dateLines.push('- "' + phrase + '" = ' + show(date) + (extra ? '  ' + extra : ''));
};
const msgText = clean(trigger.text);
const DAYRE = '(sunday|monday|tuesday|wednesday|thursday|friday|saturday)';
let dm;

const reNext = new RegExp('\\bnext\\s+' + DAYRE + '\\b', 'gi');
while ((dm = reNext.exec(msgText)) !== null)
  note(dm[0], addDays(weekMonday, 7 + ((dayIndex(dm[1]) + 6) % 7)));

const reThis = new RegExp('\\bthis\\s+' + DAYRE + '\\b', 'gi');
while ((dm = reThis.exec(msgText)) !== null)
  note(dm[0], addDays(weekMonday, (dayIndex(dm[1]) + 6) % 7));

// A bare weekday is the next one coming up, which is not the same as
// "next <day>" - worth saying out loud rather than assuming they agree.
const reBare = new RegExp('(?<!\\b(?:next|this|last)\\s)\\b' + DAYRE + '\\b', 'gi');
while ((dm = reBare.exec(msgText)) !== null) {
  let target = addDays(weekMonday, (dayIndex(dm[1]) + 6) % 7);
  if (target.getTime() < today.getTime()) target = addDays(target, 7);
  note(dm[0], target, '(the next one - if they meant the week after, that is "next ' + dm[1] + '")');
}
if (/\btomorrow\b/i.test(msgText)) note('tomorrow', addDays(today, 1));
if (/\b(today|tonight)\b/i.test(msgText)) note('today', today);
if (pastHit) note(pastHit.shown, new Date(Date.UTC(pastHit.y, pastHit.mo, pastHit.d)));

// A follow-up that says "that slot" carries no date phrase, so nothing above
// fires and the model works the date out again from memory. On 2026-08-30 "what
// are all my options for that slot?" was answered from 2027-09-16 availability
// in a conversation about the 9th. So the resolved date is remembered and stated
// back on the turns that do not name one. Any date in the message wins over it,
// and a reset clears it.
// Bounded to this conversation and this day. Without that it would still be
// answering about last Thursday a week later - the epoch changes on reset and
// the day stamp changes at midnight, and either one retires it.
const dateKey = 'lastdate_' + slackUser;
const todayStamp = today.toISOString().slice(0, 10);
if (isReset) { delete store[dateKey]; }
else if (primaryDate) {
  store[dateKey] = { date: primaryDate.toISOString().slice(0, 10), epoch: epoch, day: todayStamp };
}
const carriedRec = store[dateKey];
const carriedOk = Boolean(carriedRec && carriedRec.date
                          && carriedRec.epoch === epoch && carriedRec.day === todayStamp);

// A question about which rooms exist is not a question about a day. Asked
// "list all the rooms" straight after an availability check on 2026-08-30, she
// inherited that window and answered with the free rooms only - Katha, Salin,
// M2, M4 and M6 missing because they were busy, presented as the whole list.
// The carried date is dropped for a catalogue question. A date written in this
// message still wins, and anything asking what is free is left alone.
const asksCatalogue = /\b(list|what|which|show)\b/i.test(msgText)
  && /\b(rooms?|studios?|booths?|session types?)\b/i.test(msgText)
  && !/\b(free|available|open|booked|busy|taken|vacant)\b/i.test(msgText);

let dateNotice = '';
if (dateLines.length) {
  dateNotice = 'DATES IN THIS MESSAGE, ALREADY RESOLVED. Use these exactly, including the day of the week, '
             + 'and do not work them out again:\n' + dateLines.join('\n');
} else if (carriedOk && !asksCatalogue) {
  const carried = new Date(carriedRec.date + 'T00:00:00Z');
  dateNotice = 'THE DATE UNDER DISCUSSION IS ' + show(carried) + '. Anything in this message about "that '
             + 'slot", "then", or the same booking means that date. Use it as given and do not work it out '
             + 'again. If they name a different date, that one wins.';
}

// Both suffix forms are accepted. Messages written before the change to
// (yes/no) are still in the history window this reads, so matching only the
// new form would break the first confirmation after the change.
const tail = lastBotText.trim().toLowerCase().replace(/\((?:y\/n|yes\/no)\)$/, '').trim();
const endsWith = m => found && tail.endsWith(m);
const approvalOnly = repliedSince > 0 && !sawNewRequest;

const confirmed       = endsWith(MARKERS.book)   && saidYes;
const confirmedCancel = endsWith(MARKERS.cancel) && saidYes;
// A move is one action with one approval - Move Booking creates the replacement
// and removes the original itself. Before it existed, a reschedule needed two
// separate yeses and deleted the booking after the first one.
const confirmedMove   = endsWith(MARKERS.move)   && saidYes;

// A no is worth stating too, or the model reads it as a request it did not
// understand and shows the same summary again.
// The clearing is done in code, one node before the model sees anything - but
// nothing told the model that, so from where it sits "reset" is just a word
// someone typed. It has answered "I can't reset or clear message metadata"
// on a turn where the epoch had already moved, which is a lie about work that
// had already happened. Five runs produced five different answers.
// A start time with no end. On 2026-08-30 "book a voiceover session next
// Thursday at 2pm" came back as a 2:00-5:00 PM summary: the length was invented
// and never mentioned, and a requester approving that summary has no way to see
// the assumption. Detected here because the message is the only place the
// absence is visible - by the time the model has written a summary it has
// already chosen an end. msgText is the current message, resolved further up.
const timeHits = msgText.match(/\b\d{1,2}(:\d{2})?\s*(am|pm)\b|\b([01]?\d|2[0-3]):[0-5]\d\b/gi) || [];
const hasRange = /\b(to|till|untill?|through|thru)\b|\d\s*[-\u2013\u2014]\s*\d/i.test(msgText);
// The flag has to outlive the message that raised it. On 2026-08-30 "at 2pm"
// raised it, she asked about a booth instead of summarising, and by the turn
// the summary appeared the flag was gone - the summary said 2:00-3:00 PM with
// the assumption unstated, which is the whole thing this was meant to prevent.
// So it is stored like the carried date: bounded to this conversation and this
// day, cleared by a range, an explicit length, an approved booking, or a reset.
const soKey = 'startonly_' + slackUser;
const saysLength = /\b\d+\s*(h|hr|hrs|hour|hours|min|mins|minute|minutes)\b/i.test(msgText);
if (isReset || hasRange || saysLength) { delete store[soKey]; }
else if (timeHits.length === 1) { store[soKey] = { epoch: epoch, day: todayStamp }; }
const soRec = store[soKey];
const startOnlyPending = Boolean(soRec && soRec.epoch === epoch && soRec.day === todayStamp);

const startOnlyNotice = startOnlyPending
  ? 'THEY GAVE A START TIME AND NO END TIME. Do not quietly pick a duration. Either ask how long the '
    + 'session runs, or say plainly in the summary what length you are assuming - for example "Assuming 3 '
    + 'hours, tell me if that is wrong." Never show a start and an end as though they gave you both.'
  : '';

const resetNotice = isReset
  ? 'THE CONVERSATION HAS JUST BEEN CLEARED. It already happened, before this message reached you - '
    + 'you no longer have anything from before it. Reply with exactly: All cleared. What do you need? '
    + 'Say nothing else, do not explain what reset does, and never say you cannot clear it.'
  : '';

const declineNotice = (saidNo && (endsWith(MARKERS.book) || endsWith(MARKERS.cancel) || endsWith(MARKERS.move)))
  ? 'THEY SAID NO to what you just showed them. Nothing was created and nothing was '
    + 'cancelled. Ask what they want changed. Do not show that same summary again unchanged.'
  : '';

// Book Session enforces `confirmed` itself, so the model is not told about it.
// Nothing enforces the cancel: the prompt asks the model to notice the approval
// and call Cancel Booking, and on 2026-08-30 it instead re-ran the search and
// re-presented the same summary three times running. So the approval is stated
// as a fact the same way pastDateNotice is, rather than left to be inferred.
const moveNotice = confirmedMove
  ? 'THE MOVE IS ALREADY APPROVED. Your next action is one call to Move Booking, with the booking title '
    + 'and its current date exactly as you showed them, plus the new start and end. Do not cancel anything '
    + 'and do not book anything separately - Move Booking does both. Do not show that summary again.'
  : '';

const cancelNotice = confirmedCancel
  ? 'THE CANCELLATION IS ALREADY APPROVED. They have just said yes to the summary you showed them. '
    + 'Your next action is one call to Cancel Booking, with the booking title and date exactly as you '
    + 'showed them. Do not search first - Cancel Booking finds the booking itself, and searching instead '
    + 'of cancelling is the one failure this notice exists to stop. Do not present that summary again '
    + 'and do not ask again. When it comes back, say what it tells you and nothing more.'
  : '';

return [{ json: Object.assign({}, booker, {
  pastDate: pastDate,
  pastDateNotice: pastDateNotice,
  dateNotice: dateNotice,
  cancelNotice: cancelNotice,
  moveNotice: moveNotice,
  declineNotice: declineNotice,
  resetNotice: resetNotice,
  startOnlyNotice: (confirmed ? '' : startOnlyNotice),
  epoch: epoch,
  confirmed: confirmed,
  confirmedCancel: confirmedCancel,
  confirmedMove: confirmedMove,
  gate: { presentedBook: endsWith(MARKERS.book), presentedCancel: endsWith(MARKERS.cancel), presentedMove: endsWith(MARKERS.move),
          repliedSince: repliedSince, sawNewRequest: sawNewRequest, said: said, saidYes: saidYes, saidNo: saidNo, sawBotMessage: found,
          historyCount: msgs.length, lastBotText: lastBotText.slice(-120) }
}) }];

// Builds the room-ranking reference the system prompt interpolates. The lists
// live in Airtable as record ids the model cannot read, and it will not call a
// tool to resolve them - so they are resolved here and handed to it as text.
const nameOf = {};
// Conference rooms are read out of Airtable rather than named here, so adding
// one does not need a code change. Room Type carries "Conference Room" for
// Salin, Likha and Katha.
const isConference = {};
// Vocal booths come from the `Vocal Booth` checkbox, never from Room Type.
// Room Type marks Studio E as a Recording Booth, but E is the video and colour
// grading room - on 2026-09-01 she was offering it as a go-to booth pairing
// because Room Type was the only booth signal reaching her. The checkbox is
// already correct in Airtable (A, B and D); nothing was reading it. Tick the
// box on another room and it appears here with no code change.
const vocalBooths = [];
const otherBooths = [];
try {
  for (const it of $('All Rooms').all()) {
    const r = (it && it.json) || {};
    const f = r.fields || {};
    if (!r.id) continue;
    const nm = String(f['Room Name'] || '').trim();
    nameOf[r.id] = nm;
    const kinds = [].concat(f['Room Type'] || []).map(x => String(x).toLowerCase());
    if (kinds.indexOf('conference room') !== -1) isConference[nm.toLowerCase()] = true;
    if (f['Vocal Booth'] === true) vocalBooths.push(nm);
    else if (kinds.indexOf('recording booth') !== -1) otherBooths.push(nm);
  }
} catch (e) {}

const lines = [];
try {
  for (const it of $('All Session Types').all()) {
    const f = ((it && it.json) || {}).fields || {};
    const type = String(f['Type'] || '').trim();
    if (!type) continue;
    const names = ids => [].concat(ids || []).map(i => nameOf[i]).filter(Boolean);
    const pri = names(f['Priority']), last = names(f['Last Resort']);
    if (!pri.length && !last.length) continue;
    // "Priority" and "Last Resort" are the Airtable column names, not words a
    // requester should ever hear - Tara, 2026-08-30. She read them straight out
    // of this table and told someone a room was "a last-resort choice", which
    // sounds like a rule when it is a preference. The distinction still drives
    // the guards; only the wording changed.
    // A conference room is never Jessie's to pick - the requester has to ask for
    // one and say which. That rule used to live only in a distant paragraph of
    // the prompt, and on 2026-08-30 she offered Likha, Katha and Salin for a
    // Celebrity Recording unprompted. Book Session cannot catch it either,
    // because they are legitimately on that session type's list. So the
    // constraint travels with the names instead.
    const conf = c => c.filter(r => isConference[r.toLowerCase()]);
    const plain = c => c.filter(r => !isConference[r.toLowerCase()]);
    const confRooms = conf(pri.concat(last)).filter((r, i, a) => a.indexOf(r) === i);
    const priPlain = plain(pri);
    // Four session types list the same room as both Priority and Last Resort -
    // VO Recording and Event have identical lists - which produced
    // "Lobby · also possible: Lobby". A room already offered is not an
    // alternative to itself.
    const lastPlain = plain(last).filter(r => priPlain.indexOf(r) === -1);
    const parts = [];
    if (priPlain.length)  parts.push('normally: ' + priPlain.join(', '));
    if (lastPlain.length) parts.push('also possible: ' + lastPlain.join(', '));
    // For a Meeting every room is a conference room, so this is the whole list
    // rather than a caveat on it - saying "normally: none on file" would read
    // as though Meetings have nowhere to go.
    if (confRooms.length) parts.push('conference rooms, ask which before booking: ' + confRooms.join(', '));
    if (!parts.length) parts.push('no rooms on file');
    lines.push('- ' + type + ' — ' + parts.join(' · '));
  }
} catch (e) {}

lines.sort();

// The session types, read live, so the list she offers cannot go stale when Tel
// adds one - which had already happened: Localization Atmos Mixing existed in
// Airtable and appeared nowhere in the prompt.
const typeNames = [];
try {
  for (const it of $('All Session Types').all()) {
    const t = String((((it && it.json) || {}).fields || {})['Type'] || '').trim();
    if (t && typeNames.indexOf(t) === -1) typeNames.push(t);
  }
} catch (e) {}
typeNames.sort();

// A department-flavoured e.g. for the session-type question. Not a filter -
// bookers routinely book outside their own department, and eight of the eleven
// departments map to no session type at all. The full list stays available.
const DEPT_ROLES = {
  'audio post':   ['post engineer'],
  'localization': ['loc engineer'],
  'music':        ['music engineer', 'music arranger']
};
const bookerFields = (function(){ try { return ($('Get Booker').first().json || {}).fields || {}; }
                                  catch (e) { return {}; } })();
const myRoles = [];
for (const d of [].concat(bookerFields['Department'] || [])) {
  for (const r of (DEPT_ROLES[String(d).trim().toLowerCase()] || [])) myRoles.push(r);
}
const suggested = [];
if (myRoles.length) {
  try {
    for (const it of $('All Session Types').all()) {
      const f = ((it && it.json) || {}).fields || {};
      const t = String(f['Type'] || '').trim();
      if (!t) continue;
      const roles = [].concat(f['Engineer Role Required'] || []).map(r => String(r).trim().toLowerCase());
      if (roles.some(r => myRoles.indexOf(r) !== -1) && suggested.indexOf(t) === -1) suggested.push(t);
    }
  } catch (e) {}
}
suggested.sort();
const sessionTypeHint = suggested.length ? suggested.join(', ') : '';
const sessionTypes = typeNames.length
  ? typeNames.join(' · ')
  : '(session type list unavailable this run - ask Session Types before offering any)';
let text = lines.length
  ? lines.join('\n')
  : '(room ranking unavailable this run - ask Rooms and Studios before naming any room)';
// The booth line rides on the ranking block rather than a new prompt variable,
// so the system prompt needs no change and the two cannot drift apart.
if (vocalBooths.length) {
  let boothLine = '- Vocal booths - normally: ' + vocalBooths.sort().join(' \u00b7 ') + '.';
  if (otherBooths.length) {
    boothLine += ' ' + otherBooths.sort().join(' and ')
      + (otherBooths.length > 1 ? ' are Recording Booths but not vocal booths' : ' is a Recording Booth but not a vocal booth')
      + ' - pair ' + (otherBooths.length > 1 ? 'one' : 'it')
      + ' only when the requester asks for it by name, and when you do, say the vocal booths we normally use are '
      + vocalBooths.sort().join(', ') + ' and name which of those are free.';
  }
  text += '\n' + boothLine;
}
// Reference data for the sub-workflows. Both used to re-read these two tables
// on every call, so on a booking turn the same tables were fetched three times.
// Passed down instead - resolved once, here.
const refRooms = [];
try {
  for (const it of $('All Rooms').all()) {
    const r = (it && it.json) || {}; const f = r.fields || {};
    if (r.id && f['Room Name']) {
      // `booth` is any room typed Recording Booth - it says the room CAN be paired.
      // `vocalBooth` is the checkbox and says it is one we would offer. Studio E is
      // the first: a booth, not a vocal booth. Check Conflicts needs both, because
      // the ranking check must let a paired booth through while still refusing a
      // room that is not a booth at all.
      const kindsRef = [].concat(f['Room Type'] || []).map(x => String(x).toLowerCase());
      refRooms.push({ id: r.id, name: String(f['Room Name']).trim(),
                      vocalBooth: f['Vocal Booth'] === true,
                      booth: f['Vocal Booth'] === true || kindsRef.indexOf('recording booth') !== -1 });
    }
  }
} catch (e) {}
const refTypes = [];
try {
  for (const it of $('All Session Types').all()) {
    const r = (it && it.json) || {}; const f = r.fields || {};
    const t = String(f['Type'] || '').trim();
    if (!t) continue;
    refTypes.push({ type: t, min: f['Min Duration (mins)'] || null, max: f['Max Duration (mins)'] || null,
                    priority: [].concat(f['Priority'] || []), last: [].concat(f['Last Resort'] || []) });
  }
} catch (e) {}
// --- "book Studio F for Howard" ------------------------------------------
// A name after "for" is not the client, and on 2026-08-30 she put one in the
// client field without asking: "Book Studio F for Howard" produced the title
// ORION / Howard / TL, with no lookup and no question. Howard is staff.
//
// Detected here rather than in Gate Context because only this node can see the
// session-type list, and "for Post Mixing" looks identical to "for Howard".
// Room names are excluded for the same reason. It does not try to work out what
// the name is - it only stops the client field being filled from a guess.
let forNameNotice = '';
try {
  const msg = String(($('Slack Trigger').first().json || {}).text || '')
    .replace(/\*sent using\*[\s\S]*$/i, '');
  const saidClient = /\bclients?\b/i.test(msg);
  const known = []
    .concat(typeNames.map(t => t.toLowerCase()))
    .concat(refRooms.map(r => r.name.toLowerCase()));
  const hits = [];
  const re = /\bfor\s+([A-Z][\w.'-]*(?:\s+[A-Z][\w.'-]*){0,3})/g;
  let m;
  while ((m = re.exec(msg)) !== null) {
    const phrase = m[1].trim();
    const low = phrase.toLowerCase();
    if (known.some(k => k && (low === k || low.indexOf(k) === 0 || k.indexOf(low) === 0))) continue;
    hits.push(phrase);
  }
  if (!saidClient && hits.length) {
    forNameNotice = 'THEY WROTE "for ' + hits[0] + '" AND HAVE NOT SAID WHO THE CLIENT IS. A name after '
      + '"for" is not the client - it is as likely to be the person you are booking on behalf of, or the '
      + 'project. Do not put it in the client field or the title on that basis. Ask who the client is, and '
      + 'ask what ' + hits[0] + ' is if it is still unclear, before you present any summary. Internal rooms '
      + '- M Booth, Lobby and Conference Room - have no client, so ignore this if the booking is one of those.';
  }
} catch (e) {}

// The prompt used to carry a written-out room list. Rooms come from Airtable
// already, so it is built here instead - one less list that can go stale, and
// no extra call, since All Rooms was read this turn anyway.
const roomNames = refRooms.length
  ? refRooms.map(r => r.name).join(' · ')
  : '(room list unavailable this run - ask Rooms and Studios)';

const preemptionRanks = {};
try { for (const it of $('All Session Types').all()) {
  const f = ((it && it.json) || {}).fields || {};
  const t = f['Type']; const r = Number(f['Preemption Rank']);
  if (t && Number.isFinite(r)) preemptionRanks[String(t)] = r;
} } catch (e) {}

const referenceData = (refRooms.length && refTypes.length)
  ? JSON.stringify({ rooms: refRooms, types: refTypes, preemptionRanks: preemptionRanks }) : '';

const consentNote = (function(){ try { return $('Consent Router').first().json._consentContext || ''; } catch(e){ return ''; } })();
return [{ json: Object.assign({}, $('Gate Context').first().json, { consentNote: consentNote, referenceData: referenceData, roomTable: text, sessionTypes: sessionTypes, sessionTypeHint: sessionTypeHint, forNameNotice: forNameNotice, roomNames: roomNames }) }];

// Consent-reply router - inlined from workflows/drafts/consent/router.js (13/13). FAIL-OPEN.
const rows = $input.all().map(i => (i && i.json) || {});
const trig = $('Slack Trigger').first().json || {};
const sender = String(trig.user || '');
const senderJson = ($('Get Sender').first().json) || {};
const msg = { user: sender, text: String(trig.text || ''), bot_id: trig.bot_id };
function findApproverRow(s, rows){ for(const r of (rows||[])){ if(!r) continue; if(String(r['Status']||'').toUpperCase()!=='PENDING') continue; if(String(r['Approver']||'')===s) return r; } return null; }
const row = findApproverRow(sender, rows);
const YES=['yes','y','yes.','yep','yup','ok','okay','sure','go','approve','approved','confirm','confirmed'];
const NO=['no','n','no.','nope','deny','denied','reject','rejected','decline','declined'];
function resolveConsent(t){ t=String(t==null?'':t).trim().toLowerCase().replace(/[^\w ]/g,'').trim(); if(!t) return 'unclear'; const f=t.split(/\s+/)[0]; if(YES.indexOf(t)!==-1||YES.indexOf(f)!==-1) return 'approve'; if(NO.indexOf(t)!==-1||NO.indexOf(f)!==-1) return 'reject'; return 'unclear'; }
let branch='normal';
if(msg.bot_id){ branch='ignore'; } else if(row){ branch = (resolveConsent(msg.text)==='reject') ? 'reject' : 'consent-help'; }
let consentContext='';
if(branch==='consent-help' && row){ const who=row['Approver Name']||'this booker'; const title=row['Incumbent Title']||'their booking'; const rm=row['Room/Booth']||'a room'; const reqName=row['Requester Name']||'a higher-priority booking';
  consentContext='CONSENT CONTEXT: You earlier asked '+who+' to move "'+title+'" out of '+rm+' to free it for '+reqName+', which outranks it. They are replying now. If they give a new time or room, move "'+title+'" there via the normal Move flow - present the move summary and confirm as usual. Do NOT book '+reqName+' yourself; that happens automatically once "'+title+'" moves and frees the room. If they decline, tell '+reqName+' it stays taken.'; }
return [{ json: Object.assign({}, senderJson, { _consentBranch: branch, _consentContext: consentContext, _matched: row || {} }) }];
